parameters.jsCode:
const aiResponse = $input.item.json.message.content;
let article;
try {
  article = JSON.parse(aiResponse);
} catch (e) {
  article = { error: 'Parse failed', raw: aiResponse };
}

// Build full HTML content
let htmlContent = `<p>${article.introduction || ''}</p>\n\n`;

if (article.sections) {
  for (const section of article.sections) {
    htmlContent += `<h2>${section.heading}</h2>\n`;
    htmlContent += `<p>${section.content}</p>\n`;
    if (section.subsections) {
      for (const sub of section.subsections) {
        htmlContent += `<h3>${sub.heading}</h3>\n`;
        htmlContent += `<p>${sub.content}</p>\n`;
      }
    }
  }
}

htmlContent += `<h2>Conclusion</h2>\n<p>${article.conclusion || ''}</p>\n`;

if (article.faq && article.faq.length > 0) {
  htmlContent += `<h2>FAQ</h2>\n`;
  for (const faq of article.faq) {
    htmlContent += `<h3>${faq.question}</h3>\n<p>${faq.answer}</p>\n`;
  }
}

return {
  json: {
    ...article,
    html_content: htmlContent,
    agent_id: 'content-creator',
    workflow_id: 'WF-CONTENT-BLOG',
    generated_at: new Date().toISOString()
  }
};

